def H():
    return {"User-Agent": UA, "Content-Type": "application/json",
            "Accept": "multipart/mixed, application/json, application/octet-stream, */*",
            "Accept-Language": "en-IN,en-US;q=0.9,en;q=0.8",
            "Origin": "https://www.meta.ai", "Referer": "https://www.meta.ai/",
            "Sec-Fetch-Dest": "empty", "Sec-Fetch-Mode": "cors", "Sec-Fetch-Site": "same-origin",
            "Priority": "u=1, i"}

DOC_WARMUP = "e7f802582dbfed8e181b012e010993eb"
DOC_MODE   = "c32bbe999c48e64e855dc63177d5153f"
DOC_CHECK  = "954e9b193487fa4af750af87906e4313"

def gql(s, doc_id, variables):
    return s.post(GQL, json={"doc_id": doc_id, "variables": variables}, headers=H())

def create_conversation(s):
    conv_id = str(uuid.uuid4())
    results = {}
    def warmup():
        results["warmup"] = gql(s, DOC_WARMUP, {"conversationId": conv_id})
    def mode():
        results["mode"] = gql(s, DOC_MODE, {"input": {"conversationId": conv_id, "mode": "think_fast"}})
    def check():
        results["check"] = gql(s, DOC_CHECK, {})
    ts = [threading.Thread(target=warmup, daemon=True),
          threading.Thread(target=mode, daemon=True),
          threading.Thread(target=check, daemon=True)]
    for t in ts:
        t.start()
    for t in ts:
        t.join(timeout=10)
    return conv_id

# ═══════════════ DGW SESSION (single socket reused) ═══════════════
class DGWWorker:
    def __init__(self, conv_id):
        self.conv_id = conv_id
        self.events = __import__("queue").Queue()
        self.loop = __import__("asyncio").new_event_loop()
        self.connected = threading.Event()
        self.session = None
        self.thread = threading.Thread(target=self._run, daemon=True)
        self.thread.start()

    def _run(self):
        import asyncio
        asyncio.set_event_loop(self.loop)
        self.loop.run_forever()

    def connect(self):
        import asyncio
        async def _c():
            for attempt in range(3):
                try:
                    from dgw_session import DGWSession
                    token = load_token()
                    self.session = DGWSession(token, self.conv_id, download_media=True)
                    await self.session.connect()
                    self.connected.set()
                    return
                except Exception as e:
                    self.events.put(("ws_error", f"{type(e).__name__}: {e}"))
                    await asyncio.sleep(2)
            self.connected.clear()
        asyncio.run_coroutine_threadsafe(_c(), self.loop)

    def ask(self, message, mode, attachments=None, **opts):
        import asyncio
        async def _a():
            try:
                for _ in range(50):
                    if self.session is not None and self.session._ws_open:
                        break
                    await asyncio.sleep(0.3)
                if self.session is None:
                    raise RuntimeError("no session (conversation not ready)")
                if not self.session._ws_open:
                    await self.session.connect()
                    self.connected.set()
                text, media = await self.session.ask(
                    message, mode=mode, attachments=attachments,
                    on_chunk=lambda t: self.events.put(("chunk", t)),
                    on_reasoning=lambda t: self.events.put(("reasoning", t)),
                    on_media=lambda m: self.events.put(("media", m)),
                    **opts
                )
                self.events.put(("done", text, media))
            except Exception as e:
                try:
                    token = load_token()
                    try:
                        await self.session.close()
                    except Exception:
                        pass
                    from dgw_session import DGWSession
                    self.session = DGWSession(token, self.conv_id, download_media=True)
                    await self.session.connect()
                    self.connected.set()
                    text, media = await self.session.ask(
                        message, mode=mode, attachments=attachments,
                        on_chunk=lambda t: self.events.put(("chunk", t)),
                        on_reasoning=lambda t: self.events.put(("reasoning", t)),
                        on_media=lambda m: self.events.put(("media", m)),
                        **opts
                    )
                    self.events.put(("done", text, media))
                except Exception as e2:
                    self.events.put(("error", f"{type(e2).__name__}: {e2}"))
        asyncio.run_coroutine_threadsafe(_a(), self.loop)

    def close(self):
        import asyncio
        async def _c():
            try:
                await self.session.close()
            except Exception:
                pass
            self.loop.stop()
        asyncio.run_coroutine_threadsafe(_c(), self.loop)
        self.thread.join(timeout=3)

    def discard_events(self):
        import queue
        while True:
            try:
                self.events.get_nowait()
            except queue.Empty:
                return

    def reset_session(self):
        """Drop the current socket so stray frames can't leak into the next ask."""
        import asyncio
        async def _c():
            try:
                if self.session is not None:
                    await self.session.close()
            except Exception:
                pass
            self.session = None
            self.connected.clear()
        asyncio.run_coroutine_threadsafe(_c(), self.loop)

# ═══════════════ REPL ═══════════════
def clean_chunk(s):
    """Strip raw citation markers (【123…†L2-L4】) and tidy whitespace."""
    s = re.sub(r"【[^】]*】", "", s)
    s = s.replace("†", "")
    s = re.sub(r"\n{3,}", "\n\n", s)
    return s

def media_kind(m):
    """Friendly label for any attachment mime type."""
    mt = (m.get("mime_type") or "").lower()
    if mt.startswith("image/"):
        return "IMG"
    if mt.startswith("video/"):
        return "VID"
    if mt.startswith("audio/"):
        return "AUD"
    if mt.startswith("text/") or mt in (
            "application/json", "application/xml", "application/x-subrip",
            "application/rtf", "application/x-yaml"):
        return "TXT"
    if "pdf" in mt:
        return "PDF"
    if "wordprocessing" in mt or "spreadsheet" in mt or "presentation" in mt:
        return "DOC"
    if "zip" in mt or "gzip" in mt or "tar" in mt:
        return "ARC"
    return "FILE"

def chat(s):
    mode = "instant"
    show_thinking = False
    # Extended Web-UI opts (all map to proto fields; defaults match web)
    opts = {"temperature": None, "top_p": None, "max_tokens": None, "thinking_level": None, "reasoning_effort": None, "persona_id": None, "project_id": None, "search_enabled": None, "locale": "en-US", "timezone": "Asia/Calcutta", "branch_path": "0", "reply_to": None, "system_prompt": None, "model": None, "skill_ids": None}
    print()
    print("=" * 56)
    print("  Meta AI Chat  —  type /help for commands (full Web-UI coverage)")
    print("=" * 56)
    if s is None:
        print("[*] token-only mode: uuid conversation (no warmup)")
        conv = str(uuid.uuid4())
    else:
        print("[*] creating conversation…")
        conv = create_conversation(s)
    print(f"[*] conversation {conv[:8]}…")
    print("[*] connecting DGW…")
    worker = DGWWorker(conv)
    worker.connect()
    for _ in range(60):
        if worker.connected.is_set():
            print("[*] connected ✓")
            break
        time.sleep(0.2)
    else:
        print("[!] could not connect — check network / token.txt")
    print()

    history = []
    while True:
        try:
            m = input("You: ").strip()
        except (EOFError, KeyboardInterrupt):
            print("\n[*] bye!")
            break
        if not m:
            continue
        if m.lower() == "/quit" or m.lower() == "/exit":
            print("[*] bye!")
            break
        if m.lower() == "/help":
            print("""  /mode thinking|instant         switch reasoning mode (agentType 1000/1001)
    /think on|off                  show/hide reasoning trace (thinking mode)
  /img <prompt>                  generate an image (/imagine)
  /imagine <prompt> [n=1] [orientation=square|landscape|portrait]  image generation via ImagineParams
  /upload <file> [prompt]        attach file (image/video/audio/document) via rupload
  /new                           start fresh conversation (new promptSessionId)
  /branch <path>                 set branch path (promptEditConfig, web branching)
  /reply <messageId>             reply to a specific message (repliedToUniqueMessageId)
  /persona <id>                  set personaId (web UI persona switcher)
  /project <id>                  set projectId (metaAiProjectDetails)
  /convs                         (requires graphql docId) list recent conversations — see /convs_help
  /temp <0.1-2.0>                 set temperature (ModelInputOverrides)
  /topp <0.1-1.0>                 set top_p
  /maxtokens <n>                 set max_tokens / planner_model_max_tokens
  /thinking_level standard|extended   set thinkingLevel
  /reasoning low|medium|high|xhigh   set reasoningEffort (overrides thinking)
  /model <name>                  set model (planner_model / model)
  /system <prompt>               set system_prompt_template
  /search on|off                 toggle meta search (isMetasearchInlineEnabled)
  /locale <en-US|hi-IN|...>      set userLocale
  /timezone <Asia/Calcutta|...>   set clientTimezone
  /skill <id1,id2>               set skill_ids
  /convs_help                    show how to capture conversation-list doc_ids
  /login                         force fresh password login now
  /token <ecto1:...>             paste fresh DGW token (DevTools → gateway WS Authorization)
  /open <file>                   open downloaded file
  /quit                          exit
  Web-UI coverage: all proto fields (ModelInputOverrides, ClippyOverrides, ProductContext, Imagine) are now exposed.""")
            continue
        if m.lower() == "/login":
            print("[*] forcing fresh login…")
            ns = login(EMAIL, PASSWORD)
            if ns is not None:
                s = ns
                worker.close()
                conv = create_conversation(s)
                worker = DGWWorker(conv)
                worker.connect()
                print(f"[+] logged in — new conversation {conv[:8]}…")
            else:
                print("[!] login failed")
            continue
        if m.lower().startswith("/token"):
            arg = m.split(maxsplit=1)[1].strip() if len(m.split(maxsplit=1)) > 1 else ""
            if not arg:
                print("usage: /token <ecto1:...>   (DevTools → Network → dgw.meta.ai ws → Authorization param)")
                continue
            save_token(arg)
            print("[*] token saved & embedded — reconnecting…")
            worker.close()
            worker = DGWWorker(conv)
            worker.connect()
            for _ in range(30):
                if worker.connected.is_set():
                    print("[*] connected ✓"); break
                time.sleep(0.2)
            continue
        if m.lower() == "/new":
            worker.close()
            conv = (str(uuid.uuid4()) if s is None
                    else create_conversation(s))

            worker = DGWWorker(conv)
            worker.connect()
            print(f"[*] new conversation {conv[:8]}…")
            continue
        if m.lower().startswith("/mode"):
            arg = m.split(maxsplit=1)[1].strip() if len(m.split(maxsplit=1)) > 1 else ""
            if arg and arg in ("thinking", "think"):
                mode = "thinking"; print("[*] mode → THINKING")
            else:
                mode = "instant"; print("[*] mode → INSTANT")
            continue
        if m.lower().startswith("/think"):
            arg = m.split(maxsplit=1)[1].strip() if len(m.split(maxsplit=1)) > 1 else ""
            show_thinking = arg in ("on", "1", "true", "yes")
            print(f"[*] thinking trace → {'ON' if show_thinking else 'OFF'}")
            continue
        if m.lower().startswith("/temp"):
            arg = m.split(maxsplit=1)[1].strip() if len(m.split(maxsplit=1)) > 1 else ""
            try:
                opts["temperature"] = float(arg)
                print(f"[*] temperature → {opts['temperature']}")
            except:
                opts["temperature"] = None
                print("[*] temperature cleared")
